dir:





































  &DefaultButton;




function dir$dmcong(p){
  this.constructor(p);
}
dir$dmcong.prototype = new DirEvent();
dir$dmcong.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmcong.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmcongDisabledMasterField(p, g);

}

function dir$dmcongDisabledMasterField(p, g){

  if(p.valForm('ma_cong').trim() != '')
  {
    p.setDisabled('ma_cong', true);
  }
  else
  {
    p.setDisabled('ma_cong', false);
  }
}








declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã container đã tồn tại' else N'Container Code is exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã container đã tồn tại' else N'Container Code is exists' end
